 93	// The zero case of the rule: the invariant names a naked planet *beside a walled sibling*. A lone
 94	// planet has no sibling, so nothing hoists the wall for it -- it takes the ordinary floor.
 95	test('a one-planet account is walled without a sibling to point at', function (): void {
 96	    $situation = Situation::of($this)
 97	        ->resources(50_000_000, 50_000_000, 50_000_000)
 98	        ->level('robot_factory', 2)
 99	        ->level('shipyard', 4)
