126	/** @return list<int> the account's planets (moons excluded) that hold no defence, ordered or built */
127	function nakedPlanets(int $playerId): array
128	{
129	    return Planet::query()->where('user_id', $playerId)->where('planet_type', 1)->pluck('id')
130	        ->map(static fn ($id): int => (int) $id)
131	        ->filter(static function (int $id): bool {
132	            $planet = app(PlanetServiceFactory::class)->make($id, true);
133	
134	            return $planet === null || app(DefenseNeedEvaluator::class)->standingUnits($planet) === 0;
135	        })->values()->all();
136	}
