  122	    /**
  123	     * The candidate lists in the order the planner tries them. A warehouse about to overflow stops
  124	     * that planet producing, so its pass runs across every planet before any routine step; a full
  125	     * warehouse (E7) is a spend signal and comes next; then the routine economy: energy before it
  126	     * throttles, the chain's facilities, the fastest-paying mine. Public so a read-out explains a
  127	     * planet with the same lists the decision used.
  128	     *
  129	     * @return array<string, callable(PlanetService): list<BuildCandidate>>
  130	     */
  131	    public function passes(AiProfile $profile): array
  132	    {
  133	        return [
  134	            // A planet holding no defence while a sibling already stands a wall is past the
  135	            // account's opening with a sibling walled everywhere else: the facilities the wall
  136	            // itself waits on come before the economy, so the planet is not left naked behind a
  137	            // stock it is busy spending (QUAL-003).
  138	            'wall' => fn (PlanetService $planet): array => $this->facilityChain->wallPending($planet),
  139	            'storage' => fn (PlanetService $planet): array => $this->economyUpgrades->storage($planet, $profile),
  140	            'surplus' => fn (PlanetService $planet): array => $this->economyUpgrades->spendSurplus($planet, $profile),
  141	            'routine' => fn (PlanetService $planet): array => [
  142	                ...$this->energyCapacity->pending($planet),
  143	                ...$this->facilityChain->pending($planet),
  144	                ...$this->economyUpgrades->storageForPrice($planet, $profile),
  145	                ...$this->economyUpgrades->production($planet, $profile),
  146	            ],
  147	        ];
  148	    }
