  150	    /**
  151	     * The build queue and the lab run side by side, so a planet's building and the account's one
  152	     * technology are separate steps: a planet whose best candidate is a technology still builds.
  153	     *
  154	     * @param array<int|string, QueueableBuilding|QueueableResearch> $steps
  155	     * @param callable(PlanetService): list<BuildCandidate> $pass
  156	     * @return array<int|string, QueueableBuilding|QueueableResearch>
  157	     */
  158	    private function withStep(array $steps, PlanetService $planet, AiProfile $profile, callable $pass, ?SavingsGoal $goal): array
  159	    {
  160	        $candidates = $pass($planet);
  161	        $isResearch = static fn (BuildCandidate $candidate): bool => ObjectService::getObjectById($candidate->buildingId)->type === GameObjectType::Research;
  162	
  163	        // The candidate list is in priority order, so whichever queue its first entry belongs to is tried first.
  164	        $queues = [$planet->getPlanetId() => false, self::LAB_STEP => true];
  165	        if ($candidates !== [] && $isResearch($candidates[0])) {
  166	            $queues = array_reverse($queues, true);
  167	        }
  168	
  169	        foreach ($queues as $key => $research) {
  170	            if (isset($steps[$key])) {
  171	                continue;
  172	            }
  173	
  174	            $step = $this->firstQueueable($planet, $profile, array_values(array_filter($candidates, static fn (BuildCandidate $candidate): bool => $isResearch($candidate) === $research)), $goal);
  175	            if ($step !== null) {
  176	                $steps[$key] = $step;
  177	            }
  178	        }
  179	
  180	        return $steps;
  181	    }
